// The real PDF path: PDFium opens a password-protected statement (RC4-128,
// the owner's e-statement scheme), returns positioned words, and the table
// builder reconciles every row. Fixtures are generated by
// tool/make_statement_pdf.py from the synthetic statements (fake data).
import 'package:finnance_app/services/statement/pdf_words.dart';
import 'package:finnance_app/services/statement/statement_importer.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:pdfrx_engine/pdfrx_engine.dart' show pdfrxInitialize;

Future<void> _init() => pdfrxInitialize();

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('a locked statement opens with its password and reconciles', () async {
    final words = await readPdfWords(
      'test/fixtures/pdf/sbi_layout_c_locked.pdf',
      password: '98765150890',
      initialize: _init,
    );
    final s = const StatementImporter().parse(words);
    expect(s.rows, hasLength(15));
    expect(s.verifiedRows, 15);
    expect(s.closingBalancePaise, 17271770);
  });

  test('a plain OnlineSBI statement (wrapped years) reconciles', () async {
    final words = await readPdfWords('test/fixtures/pdf/sbi_layout_b.pdf', initialize: _init);
    final s = const StatementImporter().parse(words);
    expect(s.rows, hasLength(15));
    expect(s.verifiedRows, 15);
  });

  test('no password and a wrong password are told apart', () async {
    await expectLater(
      readPdfWords('test/fixtures/pdf/sbi_layout_c_locked.pdf', initialize: _init),
      throwsA(isA<PdfNeedsPassword>()),
    );
    await expectLater(
      readPdfWords(
        'test/fixtures/pdf/sbi_layout_c_locked.pdf',
        password: '12345',
        initialize: _init,
      ),
      throwsA(isA<PdfWrongPassword>()),
    );
  });
}
